//! informed entities, so no consumer joins rt by hand (tests/rt_join_law_test,
//! tests/alert_test). The types in [`gtfs_rt`] are generated by `build.rs`.

pub mod gtfs_rt {
    include!(concat!(env!("OUT_DIR"), "/transit_realtime.rs"));
}

